use sqlx::{PgPool, Postgres, QueryBuilder, Row};

use crate::error::{ApiError, ApiResult};
use crate::models::account::{
    Account, AccountBalance, CreateAccount, NormalBalance, UpdateAccount,
};

pub async fn create_account(pool: &PgPool, input: &CreateAccount) -> ApiResult<Account> {
    // ID will be generated by database bigid() function
    let normal_str = match input.normal {
        NormalBalance::Debit => "DR",
        NormalBalance::Credit => "CR",
    };

    let record = sqlx::query!(
        r#"
        INSERT INTO account (ledger_id, parent_id, name, number, normal)
        VALUES ($1, $2, $3, $4, $5)
        RETURNING id, ledger_id, parent_id, name, number, normal, version, created
        "#,
        input.ledger_id,
        input.parent_id,
        input.name,
        input.number,
        normal_str
    )
    .fetch_one(pool)
    .await?;

    Ok(Account {
        id: record.id,
        ledger_id: record.ledger_id,
        parent_id: record.parent_id,
        name: record.name,
        number: record.number,
        normal: match record.normal.as_str() {
            "DR" => NormalBalance::Debit,
            "CR" => NormalBalance::Credit,
            _ => NormalBalance::Debit,
        },
        version: record.version,
        created: record.created,
    })
}

pub async fn create_accounts_batch(
    pool: &PgPool,
    inputs: &[CreateAccount],
) -> ApiResult<Vec<Account>> {
    // Start a transaction to ensure atomicity
    let mut tx = pool.begin().await?;

    let mut accounts = Vec::new();

    for input in inputs {
        let normal_str = match input.normal {
            NormalBalance::Debit => "DR",
            NormalBalance::Credit => "CR",
        };

        let record = sqlx::query!(
            r#"
            INSERT INTO account (ledger_id, parent_id, name, number, normal)
            VALUES ($1, $2, $3, $4, $5)
            RETURNING id, ledger_id, parent_id, name, number, normal, version, created
            "#,
            input.ledger_id,
            input.parent_id,
            input.name,
            input.number,
            normal_str
        )
        .fetch_one(&mut *tx)
        .await?;

        accounts.push(Account {
            id: record.id,
            ledger_id: record.ledger_id,
            parent_id: record.parent_id,
            name: record.name,
            number: record.number,
            normal: match record.normal.as_str() {
                "DR" => NormalBalance::Debit,
                "CR" => NormalBalance::Credit,
                _ => NormalBalance::Debit,
            },
            version: record.version,
            created: record.created,
        });
    }

    // Commit the transaction
    tx.commit().await?;

    Ok(accounts)
}

pub async fn get_account_by_id(pool: &PgPool, id: i64) -> ApiResult<Account> {
    let record = sqlx::query!(
        r#"SELECT id, ledger_id, parent_id, name, number, normal, version, created FROM account WHERE id = $1"#,
        id
    )
    .fetch_one(pool)
    .await
    .map_err(|e| match e {
        sqlx::Error::RowNotFound => ApiError::NotFound(format!("Account {} not found", id)),
        _ => ApiError::Database(e),
    })?;

    Ok(Account {
        id: record.id,
        ledger_id: record.ledger_id,
        parent_id: record.parent_id,
        name: record.name,
        number: record.number,
        normal: match record.normal.as_str() {
            "DR" => NormalBalance::Debit,
            "CR" => NormalBalance::Credit,
            _ => NormalBalance::Debit,
        },
        version: record.version,
        created: record.created,
    })
}

pub async fn update_account(pool: &PgPool, id: i64, input: &UpdateAccount) -> ApiResult<Account> {
    let record = sqlx::query!(
        r#"
        UPDATE account
        SET name = COALESCE($2, name)
        WHERE id = $1
        RETURNING id, ledger_id, parent_id, name, number, normal, version, created
        "#,
        id,
        input.name.as_deref()
    )
    .fetch_one(pool)
    .await
    .map_err(|e| match e {
        sqlx::Error::RowNotFound => ApiError::NotFound(format!("Account {} not found", id)),
        _ => ApiError::Database(e),
    })?;

    Ok(Account {
        id: record.id,
        ledger_id: record.ledger_id,
        parent_id: record.parent_id,
        name: record.name,
        number: record.number,
        normal: match record.normal.as_str() {
            "DR" => NormalBalance::Debit,
            "CR" => NormalBalance::Credit,
            _ => NormalBalance::Debit,
        },
        version: record.version,
        created: record.created,
    })
}

pub async fn get_account_balances(
    pool: &PgPool,
    ledger_id: i64,
    account_ids: Option<Vec<i64>>,
) -> ApiResult<Vec<AccountBalance>> {
    let balances = if let Some(ids) = account_ids {
        sqlx::query(
            r#"
            SELECT 
                e.account_id,
                e.currency,
                SUM(COALESCE(e.dr, 0) - COALESCE(e.cr, 0)) as balance
            FROM entry e
            INNER JOIN transaction t ON e.transaction_id = t.id
            WHERE t.ledger_id = $1 AND e.account_id = ANY($2)
            GROUP BY e.account_id, e.currency
            "#,
        )
        .bind(ledger_id)
        .bind(&ids)
        .map(|row: sqlx::postgres::PgRow| AccountBalance {
            account_id: row.get("account_id"),
            currency: row.get("currency"),
            balance: row.get("balance"),
        })
        .fetch_all(pool)
        .await?
    } else {
        sqlx::query(
            r#"
            SELECT 
                e.account_id,
                e.currency,
                SUM(COALESCE(e.dr, 0) - COALESCE(e.cr, 0)) as balance
            FROM entry e
            INNER JOIN transaction t ON e.transaction_id = t.id
            WHERE t.ledger_id = $1
            GROUP BY e.account_id, e.currency
            "#,
        )
        .bind(ledger_id)
        .map(|row: sqlx::postgres::PgRow| AccountBalance {
            account_id: row.get("account_id"),
            currency: row.get("currency"),
            balance: row.get("balance"),
        })
        .fetch_all(pool)
        .await?
    };

    Ok(balances)
}

/// Build the WHERE clause for account queries based on search parameters
fn build_account_filters<'a>(
    query_builder: &mut QueryBuilder<'a, Postgres>,
    params: &'a crate::api::search::AccountSearchParams,
) {
    // Handle comma-delimited list of IDs
    if let Some(ref id_list) = params.id {
        let ids: Vec<i64> = id_list
            .split(',')
            .filter_map(|s| s.trim().parse::<i64>().ok())
            .collect();
        if !ids.is_empty() {
            query_builder.push(" AND id = ANY(");
            query_builder.push_bind(ids);
            query_builder.push(")");
        }
    }

    // Handle comma-delimited list of ledger IDs
    if let Some(ref ledger_id_list) = params.ledger_id {
        let ledger_ids: Vec<i64> = ledger_id_list
            .split(',')
            .filter_map(|s| s.trim().parse::<i64>().ok())
            .collect();
        if !ledger_ids.is_empty() {
            query_builder.push(" AND ledger_id = ANY(");
            query_builder.push_bind(ledger_ids);
            query_builder.push(")");
        }
    }

    // Handle comma-delimited list of parent IDs
    if let Some(ref parent_id_list) = params.parent_id {
        let parent_ids: Vec<i64> = parent_id_list
            .split(',')
            .filter_map(|s| s.trim().parse::<i64>().ok())
            .collect();
        if !parent_ids.is_empty() {
            query_builder.push(" AND parent_id = ANY(");
            query_builder.push_bind(parent_ids);
            query_builder.push(")");
        }
    }

    // Handle comma-delimited list of version IDs
    if let Some(ref version_list) = params.version {
        let versions: Vec<i64> = version_list
            .split(',')
            .filter_map(|s| s.trim().parse::<i64>().ok())
            .collect();
        if !versions.is_empty() {
            query_builder.push(" AND version = ANY(");
            query_builder.push_bind(versions);
            query_builder.push(")");
        }
    }

    // Handle comma-delimited list of account numbers
    if let Some(ref number_list) = params.number {
        let numbers: Vec<i16> = number_list
            .split(',')
            .filter_map(|s| s.trim().parse::<i16>().ok())
            .collect();
        if !numbers.is_empty() {
            query_builder.push(" AND number = ANY(");
            query_builder.push_bind(numbers);
            query_builder.push(")");
        }
    }

    // Handle comma-delimited list of name patterns (regex patterns)
    if let Some(ref name_patterns) = params.name {
        let patterns: Vec<&str> = name_patterns.split(',').map(|s| s.trim()).collect();
        if !patterns.is_empty() {
            query_builder.push(" AND (");
            let mut first = true;
            for pattern in patterns {
                if !first {
                    query_builder.push(" OR ");
                }
                query_builder.push("name ~* ");
                query_builder.push_bind(pattern);
                first = false;
            }
            query_builder.push(")");
        }
    }

    // Handle normal balance type (DR/CR, case-insensitive, also accepts debit/credit)
    if let Some(ref normal) = params.normal {
        let normal_upper = normal.to_uppercase();
        let normal_value = match normal_upper.as_str() {
            "DR" | "DEBIT" => Some("DR"),
            "CR" | "CREDIT" => Some("CR"),
            _ => None,
        };

        if let Some(normal_val) = normal_value {
            query_builder.push(" AND normal = ");
            query_builder.push_bind(normal_val);
        }
    }
}

pub async fn search_accounts(
    pool: &PgPool,
    params: &crate::api::search::AccountSearchParams,
) -> ApiResult<Vec<Account>> {
    let limit = params.base.get_limit() as i64;
    let offset = params.base.get_offset() as i64;

    // Use QueryBuilder for dynamic SQL generation
    let mut query_builder: QueryBuilder<Postgres> = QueryBuilder::new(
        "SELECT id, ledger_id, parent_id, name, number, normal, version, created FROM account WHERE 1=1",
    );

    // Build the WHERE clause
    build_account_filters(&mut query_builder, params);

    // Add sorting based on SearchParams with whitelist validation
    const ALLOWED_COLUMNS: &[&str] = &[
        "id",
        "ledger_id",
        "parent_id",
        "name",
        "number",
        "created",
        "normal",
        "version",
    ];
    if let Some(order_clause) = params.base.parse_order_by(ALLOWED_COLUMNS) {
        query_builder.push(" ORDER BY ");
        query_builder.push(order_clause);
    } else {
        // Default ordering
        query_builder.push(" ORDER BY created DESC");
    }

    // Add pagination
    query_builder.push(" LIMIT ");
    query_builder.push_bind(limit);
    query_builder.push(" OFFSET ");
    query_builder.push_bind(offset);

    // Execute the query
    let query = query_builder.build();
    let rows = query.fetch_all(pool).await?;

    let mut accounts = Vec::new();
    for row in rows {
        let account = Account {
            id: row.try_get("id")?,
            ledger_id: row.try_get("ledger_id")?,
            parent_id: row.try_get("parent_id")?,
            name: row.try_get("name")?,
            number: row.try_get("number")?,
            normal: match row.try_get::<String, _>("normal")?.as_str() {
                "DR" => NormalBalance::Debit,
                "CR" => NormalBalance::Credit,
                _ => NormalBalance::Debit,
            },
            version: row.try_get("version")?,
            created: row.try_get("created")?,
        };
        accounts.push(account);
    }

    Ok(accounts)
}

pub async fn count_accounts(
    pool: &PgPool,
    params: &crate::api::search::AccountSearchParams,
) -> ApiResult<i64> {
    // Use QueryBuilder for dynamic SQL generation
    let mut query_builder: QueryBuilder<Postgres> =
        QueryBuilder::new("SELECT COUNT(*) as count FROM account WHERE 1=1");

    // Build the WHERE clause
    build_account_filters(&mut query_builder, params);

    // Execute the query
    let query = query_builder.build();
    let row = query.fetch_one(pool).await?;
    let count: i64 = row.try_get("count")?;

    Ok(count)
}
